mapper.select:
select * from stock_quote


        and code = #{code}


        and adjust = #{adjust}


        and trade_date = #{tradeDate}


        and trade_date >= #{tradeDateMin}


order by trade_date

select distinct code from stock_quote


        and adjust = #{adjust}


order by code

select g.sd as startDate, g.ed as endDate,
       o.open as open, g.hi as high, g.lo as low, c.close as close
from (
    select period_key, min(td) as sd, max(td) as ed, max(hi) as hi, min(lo) as lo
    from (
        select left(trade_date, 6) as period_key,
               trade_date as td, high as hi, low as lo
        from stock_quote
        where code = #{code} and adjust = #{adjust} and trade_date >= #{tradeDateMin}
    ) t
    group by period_key
    having period_key < #{currentPeriod}
) g
join stock_quote o on o.code = #{code} and o.adjust = #{adjust} and o.trade_date = g.sd
join stock_quote c on c.code = #{code} and c.adjust = #{adjust} and c.trade_date = g.ed
order by g.ed

select g.sd as startDate, g.ed as endDate,
       o.open as open, g.hi as high, g.lo as low, c.close as close
from (
    select period_key, min(td) as sd, max(td) as ed, max(hi) as hi, min(lo) as lo
    from (
        select  as period_key,
               trade_date as td, high as hi, low as lo
        from stock_quote
        where code = #{code} and adjust = #{adjust} and trade_date >= #{tradeDateMin}
    ) t
    group by period_key
    having period_key < #{currentPeriod}
) g
join stock_quote o on o.code = #{code} and o.adjust = #{adjust} and o.trade_date = g.sd
join stock_quote c on c.code = #{code} and c.adjust = #{adjust} and c.trade_date = g.ed
order by g.ed
